	public static function lang(?string $l): string { $l = strtolower(substr((string)$l, 0, 2)); return ($l === 'fr' || isset(self::L[$l])) ? $l : 'en'; }
	public static function t(string $s, string $lang): string {
		if ($lang === 'fr' || !isset(self::L[$lang])) { return $s; }
		return self::D[$s][self::L[$lang]] ?? $s;
	}
}
